cd /var/tmp/pip-scratch/opencode/egypt_report && ls page-*.jpg | wc -l && pdftotext -layout report.pdf report.txt && python3 << 'EOF'
import re, json
pages = open('report.txt', encoding='utf-8').read().split('\f')
pats = {
 'exec': r'^Executive Summary\s*$','h1:1':r'^1\s+Project Overview','h1:2':r'^2\s+Data Sources','h1:3':r'^3\s+Data Model','h1:4':r'^4\s+DAX Measures','h1:5':r'^5\s+Dashboard Overview','h1:6':r'^6\s+Page 1','h1:7':r'^7\s+Page 2','h1:8':r'^8\s+Page 3','h1:9':r'^9\s+Page 4','h1:10':r'^10\s+Key Insights','h1:11':r'^11\s+Recommended Actions','h1:12':r'^12\s+Data Quality','h1:13':r'^13\s+Historical Context','h1:14':r'^14\s+Conclusion\s*$','references':r'^References\s*$','hA':r'^Appendix A','hB':r'^Appendix B','hC':r'^Appendix C','hD':r'^Appendix D',
}
found = {}
for k,p in pats.items():
    hits = [i+1 for i,pg in enumerate(pages) if re.compile(p,re.M).search(pg) and i+1>3]
    found[k] = hits[0] if hits else None
prev = json.load(open('tocmap.json'))
print('pages:', len(pages)-1, 'same:', prev==found, 'missing:', [k for k,v in found.items() if v is None])
if prev != found: json.dump(found, open('tocmap.json','w'))
EOF
